import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"隨","description":"周易集解 - 隨","frontmatter":{"title":"隨","description":"周易集解 - 隨"},"headers":[],"relativePath":"zh/classics/jijie/017.md","filePath":"zh/classics/jijie/017.md"}'),l={name:"zh/classics/jijie/017.md"};function n(d,a,t,p,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="隨" tabindex="-1">隨 <a class="header-anchor" href="#隨" aria-label="Permalink to “隨”">​</a></h1><h2 id="隨-1" tabindex="-1">隨 <a class="header-anchor" href="#隨-1" aria-label="Permalink to “隨”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>隨，元亨利貞，無咎。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：豫必有隨也，故受之以隨。</p><p>韓康伯曰：順以動者，眾之所隨。</p><p>虞翻曰：否上之初，剛來下柔，初上得正，故元享利貞，無咎。</p><p>鄭玄曰：震，動也。兌，悅也。內動之以德，外悅之以言，則天下之人，咸慕其行，而隨從之，故謂之隨也。既見隨從，能長之以善，通其嘉禮，和之以義，乾之以正，則功成而有福，若無此四德，則有凶咎焉。焦贛曰：漢高帝與項籍，其明徵也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：隨，剛來而下柔，動而悅，隨。大亨貞，無咎。而天下隨時，隨時之義大矣哉。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>虞翻曰：否乾上來之坤初，故剛來而下柔。動，震，悅，兌也。</p><p>荀爽曰：隨者，震之歸魂。震歸從巽，故大通。動爻得正，故利貞。陽降陰升，嫌於有咎。動而得正，故無咎。</p><p>虞翻曰：乾為天，坤為下，震春兌秋。三四之正，坎冬離夏。四時位正，時行則行，故天下隨時矣。</p><p>蜀才曰：此本否卦。剛自上來居初，柔自初而升上，則內動而外悅，是動而悅隨也。相隨而大亨無咎。得於時也。得時，則天下隨之矣。故曰隨時之義大矣哉。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：澤中有雷，隨。君子以嚮晦入宴息。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>《九家易》曰：兌澤震雷，八月之時。雷藏於澤，則天下隨時之象也。</p><p>崔元曰：晦者，冥也。雷者，陽氣，春夏用事。今在澤中，秋冬時也。故君子象之。日出視事，其將晦冥，退入宴寢而休息也。</p><p>侯果曰：坤為晦，乾之上九來入坤初，嚮晦者也。坤初升兌，兌為休息入宴者也。欲君民者，晦德息物，動悅黎庶，則萬方歸隨也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，官有渝，貞吉。出門交有功。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>《九家易》曰：渝，變也。謂陽來居初，德正為震。震為子，得土之位故曰官也。陰陽出門，相與交通，陰往之上，亦不失正，故曰貞吉而交有功。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：官有渝，從正吉也。出門交有功，不失也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>鄭玄曰：震為大塗，又為日門。當春分，陰陽之所交也。是臣出君門，與四方賢人交有成功之象也。昔舜慎徽五典，五典克從。納於百揆，百揆時序。賓於四門，四門穆穆。是其義也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，係小子，失丈夫。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：應在巽。巽為繩，故稱係。小子謂五，兌為少，故曰小子。丈夫謂四，體大過老夫，故稱丈夫。承四隔三，故失丈夫。三至上，有大過象，故與老婦、士夫同義。體咸象，夫死大過，故每有欲嫁之義也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：係小子，弗兼與也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：已係於五，不兼與四也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，係丈夫，失小子，隨有求，得。利居貞。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：隨家陰隨陽，三之上無應。上係於四，失初小子，故係丈夫，失小子。艮為居、為求，謂求之正。得位遠應，利上承四，故利居貞矣。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：係丈夫，志捨下也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>王弼曰：雖體下卦，二已據初，將何所附，故舍初係四，志在丈夫也。四俱無應，亦欲於已隨之，則得其求矣，故曰｢隨有求，得｣也。應非其正，以係於人，何可以妄，故利居貞也。初處已下，四處已上，故曰係丈夫，失小子也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，隨有獲，貞凶。有孚在道，以明，何咎。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：謂獲三也，失位相據，在大過，死象，故貞凶。《象》曰｢其義凶矣｣。孚謂五。初震為道。三已之正，四變應初，得位在離。故｢有孚在道，以明，何咎｣。《象》曰｢明功也｣。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：隨有獲，其義凶也。有孚在道，明功也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：死在大過，故凶也。</p><p>虞翻曰：功謂五也。三四之正，離為明，故明功也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五：孚於嘉吉。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：坎為孚，陽稱嘉，位五正，故吉也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：孚於嘉，吉，位正中也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：凡五言中正，中正皆陽得其正，以此為例矣。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六：拘係之，乃從維之。王用亨於西山。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：應在艮。艮手為拘，巽為繩，兩係稱維，故｢拘係之，乃從維之｣。在隨之上，而無所隨，故維之。《象》曰｢上窮｣。是其義也。</p><p>虞翻曰：否乾為王，謂五也。有觀象，故亨。兌為西，艮為山，故｢王用亨於西山｣也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：拘係之，上窮也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：乘剛無應，故上窮也。</p>',72)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
